import type { ComponentProps } from 'react'
import { cn } from '@/lib/utils'
import styles from './Container.module.css'

export interface ContainerProps extends ComponentProps<'div'> {
  /** The widest the content gets: `sm` 48rem, `md` 64rem, `lg` 80rem. */
  size?: 'sm' | 'md' | 'lg'
  /**
   * Adds the page's side padding, `--space-container` and `--space-section`
   * from a 64rem viewport. Leave it off inside an App Shell: App Content
   * already pads the page.
   */
  padded?: boolean
}

/**
 * Caps the width of a page's content and centres it in the space it is
 * given. It owns no landmark and no surface; inside an App Shell, App
 * Content keeps the padding, the scroll and the aside column.
 */
export function Container({ size = 'md', padded = false, className, ...props }: ContainerProps) {
  return <div className={cn(styles.container, padded && styles.padded, className)} data-size={size} {...props} />
}

/* The width caps the content, not the padding: a padded and an unpadded
   Container of one size give the same line length. Sizes after Tailwind's
   max-w-3xl, 5xl and 7xl. Full width up to the cap, so it fills a grid or
   flex parent the same as a block one. */
.container {
  --container-max: 64rem;
  --container-padding: 0px;
  inline-size: 100%;
  max-inline-size: calc(var(--container-max) + 2 * var(--container-padding));
  margin-inline: auto;
  padding-inline: var(--container-padding);
}
.container[data-size='sm'] {
  --container-max: 48rem;
}
.container[data-size='lg'] {
  --container-max: 80rem;
}

/* Padding follows the viewport, not a container: a padded Container sits
   outside the App Shell, where no ancestor is a size container. The steps
   use App Content's tokens and 64rem step, so a page's sides match in and
   out of the shell. */
.padded {
  --container-padding: var(--space-container);
}
@media (width >= 64rem) {
  .padded {
    --container-padding: var(--space-section);
  }
}
